// Corndogs' own CSIL-RPC transport carrier: hand-written, NOT generated by csilgen.
// A persistent TCP connection framed with the canonical 4-byte big-endian length
// prefix (the CSIL StreamCarrier). You do not need to write a carrier or read
// csilgen docs — point this at a corndogs server's TCP address and hand it to the
// generated client:
//
//   var gpa = std.heap.GeneralPurposeAllocator(.{}){};
//   const alloc = gpa.allocator();
//   var tr = try corndogs_transport.Transport.connect(alloc, "localhost:5080");
//   defer tr.close();
//   const stop = try tr.startHeartbeat(alloc, 15 * std.time.ns_per_s); // keep it alive
//   defer stop.stop();
//   const svc = client.CorndogsClient.init(tr.asCsilgenTransport());
//
// Synchronous, one call in flight at a time: every call() is serialized under a
// mutex (matching the sync CsilgenTransport seam the generated client expects). The
// connection is dialed lazily on first use (eagerly in connect()) and re-dialed on
// failure. This carrier owns only the envelope + framing + connection; the
// generated client and codec.gen.zig own (de)serialization of typed payloads.
//
// Zig's generic CBOR `Value` (codec.gen.zig) has a public type but its generic
// encoder/decoder (`w_value`, `decode_value`) are private module-internal helpers —
// so this carrier hand-frames the small, fixed-shape CSIL-RPC envelope itself (a
// handful of small append/read functions below), the same way the Zig CSIL-Events
// TLS carrier in genquickstart.md hand-frames its envelope. The one exception is
// the ServiceError payload, which reuses the generated, public
// `codec.decode_ServiceError` — no need to hand-roll that.

const std = @import("std");
const builtin = @import("builtin");
const client = @import("client.gen.zig");
const codec = @import("codec.gen.zig");
const types = @import("types.gen.zig");

/// RFC 8949 §3.4.5.1 — embedded encoded CBOR data item ("tag 24").
const TAG_ENCODED_CBOR: u64 = 24;
/// Control-plane heartbeat: service/op the server always understands, even before
/// any application service is registered. Never collides with an app op.
const CONTROL_SERVICE = "CorndogsService";
const OP_PING = "$ping";
/// Frame size guard: refuse to send/receive a frame bigger than this.
const MAX_FRAME: usize = 256 << 20;
const DEFAULT_HEARTBEAT_INTERVAL_NS: u64 = 15 * std.time.ns_per_s;

/// A service-level error surfaced by the server (the "ServiceError" envelope
/// variant), decoded with the generated `types.ServiceError` shape.
pub const ServiceError = types.ServiceError;

/// Errors this transport can return.
///   - `TransportStatus`: the envelope's transport-level `status` was non-zero —
///     read `Transport.last_transport_error` for the server's message.
///   - `ServiceErrorOccurred`: the server replied with a typed service error (the
///     "ServiceError" envelope variant) — read `Transport.last_service_error` for
///     the code/message.
/// Both `last_*` fields are valid only until the next call on this transport
/// begins (single-in-flight, so that's the next line of caller code in the common
/// case); they are reset at the start of every call.
pub const TransportError = error{
    InvalidAddress,
    Closed,
    ConnectionClosed,
    FrameTooLarge,
    MalformedEnvelope,
    TransportStatus,
    ServiceErrorOccurred,
} || std.mem.Allocator.Error || std.net.Stream.ReadError || std.net.Stream.WriteError || std.net.TcpConnectToHostError;

/// Sync CSIL-RPC transport over one persistent TCP connection. One call in flight
/// at a time (serialized by `mutex`); the connection re-dials on failure. Safe for
/// concurrent use from multiple threads (they simply queue behind the mutex).
/// Implements the generated `client.CsilgenTransport` seam via `asCsilgenTransport`.
pub const Transport = struct {
    alloc: std.mem.Allocator, // used to (re)dial and to grow the internal read/write scratch
    host: []u8, // owned copy
    port: u16,

    mutex: std.Thread.Mutex = .{},
    stream: ?std.net.Stream = null,
    next_id: u64 = 0,
    closed: bool = false,

    /// Set right before a call returns `error.ServiceErrorOccurred`. See
    /// `TransportError` for lifetime. Not thread-safe to read from a different
    /// thread than the one that made the call.
    last_service_error: ?ServiceError = null,
    /// Set right before a call returns `error.TransportStatus`; owned (freed/
    /// replaced on the next call or on `close()`). See `TransportError` for lifetime.
    last_transport_error: ?[]u8 = null,

    hb_thread: ?std.Thread = null,
    hb_stop: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    hb_running: bool = false,

    /// Dials `addr` ("host:port") and returns a ready Transport. `allocator` is kept
    /// for the lifetime of the transport (re-dials, heartbeat bookkeeping) — use a
    /// thread-safe allocator (e.g. a `GeneralPurposeAllocator`, `page_allocator`, or
    /// `c_allocator`) if you'll call `startHeartbeat`.
    pub fn connect(allocator: std.mem.Allocator, addr: []const u8) !Transport {
        const parsed = try splitAddr(addr);
        const host_owned = try allocator.dupe(u8, parsed.host);
        errdefer allocator.free(host_owned);
        var self = Transport{ .alloc = allocator, .host = host_owned, .port = parsed.port };
        _ = try self.ensureConn();
        return self;
    }

    /// Returns the `CsilgenTransport` seam the generated `CorndogsClient` expects.
    /// `self` must outlive the client (or any in-flight call through it).
    pub fn asCsilgenTransport(self: *Transport) client.CsilgenTransport {
        return .{ .ptr = self, .call = callThunk };
    }

    fn ensureConn(self: *Transport) !std.net.Stream {
        if (self.closed) return TransportError.Closed;
        if (self.stream) |s| return s;
        const s = try std.net.tcpConnectToHost(self.alloc, self.host, self.port);
        setNoDelay(s);
        self.stream = s;
        self.next_id = 0;
        return s;
    }

    /// Closes and forgets the current connection (if it's still `bad`) so the next
    /// call re-dials. Idempotent w.r.t. a connection that was already replaced.
    fn teardown(self: *Transport, bad: std.net.Stream) void {
        if (self.stream) |cur| {
            if (cur.handle == bad.handle) {
                cur.close();
                self.stream = null;
            }
        }
    }

    /// The `CsilgenTransport.call` function pointer: encodes the envelope, sends it,
    /// reads + decodes the response, and returns the inner typed-payload bytes
    /// (allocated with `alloc`, as the generated client expects to free them).
    fn callThunk(ptr: *anyopaque, alloc: std.mem.Allocator, service: []const u8, op: []const u8, req: []const u8) anyerror![]u8 {
        const self: *Transport = @ptrCast(@alignCast(ptr));
        return self.call(alloc, service, op, req);
    }

    /// Same as the `CsilgenTransport` seam, callable directly (e.g. for the
    /// heartbeat, or if you want to drive calls without going through the generated
    /// client). Serialized under `mutex`: only one call is in flight at a time.
    pub fn call(self: *Transport, alloc: std.mem.Allocator, service: []const u8, op: []const u8, req: []const u8) TransportError![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();

        self.last_service_error = null;
        if (self.last_transport_error) |old| self.alloc.free(old);
        self.last_transport_error = null;

        const stream = try self.ensureConn();
        self.next_id += 1;
        const id = self.next_id;

        const env = try encodeEnvelope(alloc, service, op, id, req);
        defer alloc.free(env);

        writeFrame(stream, env) catch |err| {
            self.teardown(stream);
            return err;
        };
        const frame = readFrame(alloc, stream) catch |err| {
            self.teardown(stream);
            return err;
        };
        defer alloc.free(frame);
        if (frame.len == 0) {
            // A zero-length read here can only mean a clean EOF (readFrame never
            // returns an empty *frame* for a real reply); the peer closed on us.
            self.teardown(stream);
            return TransportError.ConnectionClosed;
        }

        return self.parseResponse(alloc, frame);
    }

    /// Decodes one response envelope into the caller-owned inner payload bytes. A
    /// non-zero transport `status`, or a "ServiceError" variant, becomes an error
    /// (see `last_service_error` for the structured service error).
    fn parseResponse(self: *Transport, alloc: std.mem.Allocator, frame: []const u8) TransportError![]u8 {
        var r = EnvReader{ .buf = frame };
        const resp = r.readEnvelope() catch return TransportError.MalformedEnvelope;

        if (resp.status != 0) {
            self.last_transport_error = self.alloc.dupe(u8, resp.error_msg) catch null;
            return TransportError.TransportStatus;
        }
        if (!resp.has_payload) {
            return try alloc.alloc(u8, 0); // control replies (e.g. $pong) may carry no payload
        }
        if (resp.is_service_error) {
            var se: ServiceError = undefined;
            codec.decode_ServiceError(alloc, resp.payload, &se) catch {
                return TransportError.MalformedEnvelope;
            };
            self.last_service_error = se;
            return TransportError.ServiceErrorOccurred;
        }
        return alloc.dupe(u8, resp.payload);
    }

    // --- heartbeat -----------------------------------------------------------

    /// Sends one control-plane heartbeat ($ping); returns an error if the server is
    /// unreachable. Cheap; keeps an idle connection alive and detects a dead server.
    pub fn ping(self: *Transport, alloc: std.mem.Allocator) TransportError!void {
        const resp = try self.call(alloc, CONTROL_SERVICE, OP_PING, &.{});
        alloc.free(resp);
    }

    /// SYNCHRONOUS heartbeat start: blocks, pinging every `interval_ns`, until
    /// `stop` is set (checked between pings) or a ping fails (returns that error).
    /// Run it on a thread you own, or use `startHeartbeat` for the background form.
    pub fn runHeartbeat(self: *Transport, alloc: std.mem.Allocator, interval_ns: u64, stop: *std.atomic.Value(bool)) TransportError!void {
        const interval = if (interval_ns == 0) DEFAULT_HEARTBEAT_INTERVAL_NS else interval_ns;
        while (!stop.load(.acquire)) {
            std.Thread.sleep(interval);
            if (stop.load(.acquire)) return;
            try self.ping(alloc);
        }
    }

    /// A handle to stop a background heartbeat started with `startHeartbeat`.
    pub const HeartbeatHandle = struct {
        transport: *Transport,

        /// Signals the background heartbeat thread to stop and joins it. Idempotent.
        pub fn stop(self: HeartbeatHandle) void {
            self.transport.stopHeartbeatLocked();
        }
    };

    /// ASYNCHRONOUS heartbeat start: runs the heartbeat on a background
    /// `std.Thread` and returns a handle whose `.stop()` ends it (also ended by
    /// `close()`). Only one background heartbeat runs at a time; a second call
    /// returns a handle to the existing one. `alloc` is used from the background
    /// thread — pass a thread-safe allocator.
    pub fn startHeartbeat(self: *Transport, alloc: std.mem.Allocator, interval_ns: u64) !HeartbeatHandle {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.hb_running) return HeartbeatHandle{ .transport = self };
        self.hb_stop.store(false, .release);
        self.hb_running = true;
        self.hb_thread = try std.Thread.spawn(.{}, heartbeatMain, .{ self, alloc, interval_ns });
        return HeartbeatHandle{ .transport = self };
    }

    fn heartbeatMain(self: *Transport, alloc: std.mem.Allocator, interval_ns: u64) void {
        self.runHeartbeat(alloc, interval_ns, &self.hb_stop) catch {}; // dead server / closed transport ends the heartbeat
    }

    fn stopHeartbeatLocked(self: *Transport) void {
        self.mutex.lock();
        const t = self.hb_thread;
        self.hb_thread = null;
        self.hb_running = false;
        self.mutex.unlock();
        if (t) |thread| {
            self.hb_stop.store(true, .release);
            thread.join();
        }
    }

    /// Shuts the transport down: stops any heartbeat and closes the connection.
    pub fn close(self: *Transport) void {
        self.stopHeartbeatLocked();
        self.mutex.lock();
        self.closed = true;
        if (self.stream) |s| {
            s.close();
            self.stream = null;
        }
        if (self.last_transport_error) |old| self.alloc.free(old);
        self.last_transport_error = null;
        self.mutex.unlock();
        self.alloc.free(self.host);
    }
};

fn setNoDelay(s: std.net.Stream) void {
    if (builtin.os.tag == .windows) return;
    const on: c_int = 1;
    std.posix.setsockopt(s.handle, std.posix.IPPROTO.TCP, std.posix.TCP.NODELAY, std.mem.asBytes(&on)) catch {};
}

const Addr = struct { host: []const u8, port: u16 };

/// Splits "host:port" (the last ':' is the separator, so a bare IPv6 literal
/// without brackets is not supported — bracket it, `[::1]:5080`, same as Go).
fn splitAddr(addr: []const u8) !Addr {
    var a = addr;
    if (a.len >= 2 and a[0] == '[') {
        if (std.mem.lastIndexOfScalar(u8, a, ']')) |close_idx| {
            if (close_idx + 1 < a.len and a[close_idx + 1] == ':') {
                const port = std.fmt.parseInt(u16, a[close_idx + 2 ..], 10) catch return TransportError.InvalidAddress;
                return .{ .host = a[1..close_idx], .port = port };
            }
        }
        return TransportError.InvalidAddress;
    }
    const idx = std.mem.lastIndexOfScalar(u8, a, ':') orelse return TransportError.InvalidAddress;
    if (idx == 0 or idx == a.len - 1) return TransportError.InvalidAddress;
    const port = std.fmt.parseInt(u16, a[idx + 1 ..], 10) catch return TransportError.InvalidAddress;
    return .{ .host = a[0..idx], .port = port };
}

// ===== framing: 4-byte big-endian length prefix =====

fn writeFrame(stream: std.net.Stream, payload: []const u8) TransportError!void {
    if (payload.len > MAX_FRAME) return TransportError.FrameTooLarge;
    var prefix: [4]u8 = undefined;
    std.mem.writeInt(u32, &prefix, @intCast(payload.len), .big);
    try stream.writeAll(&prefix);
    try stream.writeAll(payload);
}

/// Reads exactly one length-prefixed frame. Returns a zero-length slice on a clean
/// EOF seen before any bytes of the next frame (the caller treats that as the
/// connection having closed).
fn readFrame(alloc: std.mem.Allocator, stream: std.net.Stream) TransportError![]u8 {
    var prefix: [4]u8 = undefined;
    const got = try readFull(stream, &prefix);
    if (got == 0) return alloc.alloc(u8, 0); // clean EOF between frames
    if (got < prefix.len) return TransportError.ConnectionClosed;
    const n = std.mem.readInt(u32, &prefix, .big);
    if (n > MAX_FRAME) return TransportError.FrameTooLarge;
    const buf = try alloc.alloc(u8, n);
    errdefer alloc.free(buf);
    if (n > 0) {
        const body_got = try readFull(stream, buf);
        if (body_got < n) return TransportError.ConnectionClosed;
    }
    return buf;
}

/// Reads until `buf` is full or the peer closes; returns the number of bytes
/// actually read (`< buf.len` only on a closed connection).
fn readFull(stream: std.net.Stream, buf: []u8) TransportError!usize {
    var got: usize = 0;
    while (got < buf.len) {
        const n = try stream.read(buf[got..]);
        if (n == 0) break;
        got += n;
    }
    return got;
}

// ===== minimal hand-rolled CBOR: just enough to frame/parse the CSIL-RPC envelope =====
//
// codec.gen.zig's generic `Value` tree encoder/decoder (`w_value`/`decode_value`)
// are private to that module, so the envelope — a small, fixed-shape map — is
// framed by hand here (RFC 8949 major types 0-7, canonical/definite-length only;
// this transport never needs indefinite-length items). Per-type request/response
// PAYLOADS are still (de)serialized exclusively by the generated `codec.gen.zig`
// functions; this only ever touches the outer envelope.

fn appendHead(out: *std.ArrayList(u8), major: u3, n: u64) !void {
    const mt: u8 = @as(u8, major) << 5;
    if (n < 24) {
        try out.append(mt | @as(u8, @intCast(n)));
    } else if (n < (1 << 8)) {
        try out.append(mt | 24);
        try out.append(@intCast(n));
    } else if (n < (1 << 16)) {
        try out.append(mt | 25);
        var b: [2]u8 = undefined;
        std.mem.writeInt(u16, &b, @intCast(n), .big);
        try out.appendSlice(&b);
    } else if (n < (1 << 32)) {
        try out.append(mt | 26);
        var b: [4]u8 = undefined;
        std.mem.writeInt(u32, &b, @intCast(n), .big);
        try out.appendSlice(&b);
    } else {
        try out.append(mt | 27);
        var b: [8]u8 = undefined;
        std.mem.writeInt(u64, &b, n, .big);
        try out.appendSlice(&b);
    }
}

fn appendUint(out: *std.ArrayList(u8), n: u64) !void {
    try appendHead(out, 0, n);
}
fn appendText(out: *std.ArrayList(u8), s: []const u8) !void {
    try appendHead(out, 3, s.len);
    try out.appendSlice(s);
}
fn appendBytes(out: *std.ArrayList(u8), s: []const u8) !void {
    try appendHead(out, 2, s.len);
    try out.appendSlice(s);
}

/// Encodes the CSIL-RPC request envelope: a definite-length map
/// { v:1, service:tstr, op:tstr, id:uint, payload:tag(24, bstr req) }.
fn encodeEnvelope(alloc: std.mem.Allocator, service: []const u8, op: []const u8, id: u64, req: []const u8) !([]u8) {
    var out = std.ArrayList(u8).init(alloc);
    errdefer out.deinit();
    try appendHead(&out, 5, 5); // map, 5 pairs
    try appendText(&out, "v");
    try appendUint(&out, 1);
    try appendText(&out, "service");
    try appendText(&out, service);
    try appendText(&out, "op");
    try appendText(&out, op);
    try appendText(&out, "id");
    try appendUint(&out, id);
    try appendText(&out, "payload");
    try appendHead(&out, 6, TAG_ENCODED_CBOR); // tag 24
    try appendBytes(&out, req);
    return out.toOwnedSlice();
}

const EnvCodecError = error{ Malformed, UnexpectedEof };

const Header = struct { major: u3, arg: u64 };

/// A cursor over the response envelope bytes. No allocation: string/bytes values
/// decode as slices borrowed from the input `buf` (which the caller must keep
/// alive only for the duration of one `parseResponse` call).
const EnvReader = struct {
    buf: []const u8,
    pos: usize = 0,

    fn byte(self: *EnvReader) EnvCodecError!u8 {
        if (self.pos >= self.buf.len) return EnvCodecError.UnexpectedEof;
        const b = self.buf[self.pos];
        self.pos += 1;
        return b;
    }

    fn take(self: *EnvReader, n: u64) EnvCodecError![]const u8 {
        const len: usize = @intCast(n);
        if (self.pos + len > self.buf.len) return EnvCodecError.UnexpectedEof;
        const s = self.buf[self.pos .. self.pos + len];
        self.pos += len;
        return s;
    }

    fn readHeader(self: *EnvReader) EnvCodecError!Header {
        const b = try self.byte();
        const major: u3 = @intCast(b >> 5);
        const info: u8 = b & 0x1f;
        var arg: u64 = info;
        if (info == 24) {
            arg = try self.byte();
        } else if (info == 25) {
            const s = try self.take(2);
            arg = std.mem.readInt(u16, s[0..2], .big);
        } else if (info == 26) {
            const s = try self.take(4);
            arg = std.mem.readInt(u32, s[0..4], .big);
        } else if (info == 27) {
            const s = try self.take(8);
            arg = std.mem.readInt(u64, s[0..8], .big);
        } else if (info >= 28) {
            return EnvCodecError.Malformed;
        }
        return .{ .major = major, .arg = arg };
    }

    /// Reads one text-string value (major type 3). Errors if the next item isn't one.
    fn readText(self: *EnvReader) EnvCodecError![]const u8 {
        const h = try self.readHeader();
        if (h.major != 3) return EnvCodecError.Malformed;
        return self.take(h.arg);
    }

    /// Consumes and discards one CBOR value of any shape (used to skip envelope keys
    /// this carrier doesn't know about, for forward compatibility).
    fn skipValue(self: *EnvReader) EnvCodecError!void {
        const h = try self.readHeader();
        switch (h.major) {
            0, 1 => {}, // uint / negint: value was in the header, nothing more to read
            2, 3 => _ = try self.take(h.arg), // bytes / text
            4 => { // array
                var i: u64 = 0;
                while (i < h.arg) : (i += 1) try self.skipValue();
            },
            5 => { // map
                var i: u64 = 0;
                while (i < h.arg * 2) : (i += 1) try self.skipValue();
            },
            6 => try self.skipValue(), // tag: skip the tagged content
            7 => {}, // simple/float: any extra bytes were already consumed by the header
        }
    }

    const Envelope = struct {
        status: i64 = 0,
        error_msg: []const u8 = &.{},
        has_payload: bool = false,
        payload: []const u8 = &.{},
        is_service_error: bool = false,
    };

    /// Decodes the top-level response map: { id, status, error, variant, payload }.
    /// Any of these may be absent; unknown keys are skipped.
    fn readEnvelope(self: *EnvReader) EnvCodecError!Envelope {
        const top = try self.readHeader();
        if (top.major != 5) return EnvCodecError.Malformed; // must be a map
        var out = Envelope{};
        var i: u64 = 0;
        while (i < top.arg) : (i += 1) {
            const key = try self.readText();
            if (std.mem.eql(u8, key, "status")) {
                const h = try self.readHeader();
                out.status = switch (h.major) {
                    0 => @intCast(h.arg),
                    1 => -1 - @as(i64, @intCast(h.arg)),
                    else => return EnvCodecError.Malformed,
                };
            } else if (std.mem.eql(u8, key, "error")) {
                const h = try self.readHeader();
                if (h.major == 3) {
                    out.error_msg = try self.take(h.arg);
                } else if (h.major == 7) {
                    // null: no message
                } else {
                    return EnvCodecError.Malformed;
                }
            } else if (std.mem.eql(u8, key, "variant")) {
                const h = try self.readHeader();
                if (h.major == 3) {
                    const v = try self.take(h.arg);
                    out.is_service_error = std.mem.eql(u8, v, "ServiceError");
                } else if (h.major == 7) {
                    // null/undefined variant: nothing further to read
                } else {
                    return EnvCodecError.Malformed;
                }
            } else if (std.mem.eql(u8, key, "payload")) {
                const h = try self.readHeader();
                if (h.major == 6) { // tag(24, bstr)
                    const inner = try self.readHeader();
                    if (inner.major != 2) return EnvCodecError.Malformed;
                    out.payload = try self.take(inner.arg);
                    out.has_payload = true;
                } else if (h.major == 2) { // tolerate an untagged byte string too
                    out.payload = try self.take(h.arg);
                    out.has_payload = true;
                } else if (h.major == 7) {
                    // null: no payload (e.g. a $pong control reply)
                } else {
                    return EnvCodecError.Malformed;
                }
            } else {
                // "id" and any unknown key: this carrier doesn't need "id" itself
                // (the caller correlates by having exactly one call in flight).
                try self.skipValue();
            }
        }
        return out;
    }
};

// ===== tests =====

const testing = std.testing;

test "splitAddr: host:port" {
    const a = try splitAddr("localhost:5080");
    try testing.expectEqualStrings("localhost", a.host);
    try testing.expectEqual(@as(u16, 5080), a.port);
}

test "splitAddr: bracketed IPv6" {
    const a = try splitAddr("[::1]:5080");
    try testing.expectEqualStrings("::1", a.host);
    try testing.expectEqual(@as(u16, 5080), a.port);
}

test "splitAddr: rejects a missing port" {
    try testing.expectError(TransportError.InvalidAddress, splitAddr("localhost"));
}

test "encodeEnvelope / EnvReader round-trip a tag-24 payload" {
    const alloc = testing.allocator;
    const env = try encodeEnvelope(alloc, "CorndogsService", "SubmitTask", 7, "hello");
    defer alloc.free(env);

    var r = EnvReader{ .buf = env };
    const parsed = try r.readEnvelope();
    try testing.expectEqual(@as(i64, 0), parsed.status);
    try testing.expect(parsed.has_payload);
    try testing.expectEqualStrings("hello", parsed.payload);
    try testing.expect(!parsed.is_service_error);
}

test "EnvReader: non-zero status carries the error text" {
    const alloc = testing.allocator;
    var out = std.ArrayList(u8).init(alloc);
    defer out.deinit();
    try appendHead(&out, 5, 2); // map, 2 pairs
    try appendText(&out, "status");
    try appendUint(&out, 1);
    try appendText(&out, "error");
    try appendText(&out, "boom");

    var r = EnvReader{ .buf = out.items };
    const parsed = try r.readEnvelope();
    try testing.expectEqual(@as(i64, 1), parsed.status);
    try testing.expectEqualStrings("boom", parsed.error_msg);
    try testing.expect(!parsed.has_payload);
}

test "EnvReader: ServiceError variant" {
    const alloc = testing.allocator;
    var se = types.ServiceError{ .code = 404, .message = "not found" };
    const enc = try codec.encode_ServiceError(alloc, &se);
    defer alloc.free(enc);

    var out = std.ArrayList(u8).init(alloc);
    defer out.deinit();
    try appendHead(&out, 5, 2); // map, 2 pairs
    try appendText(&out, "variant");
    try appendText(&out, "ServiceError");
    try appendText(&out, "payload");
    try appendHead(&out, 6, TAG_ENCODED_CBOR);
    try appendBytes(&out, enc);

    var r = EnvReader{ .buf = out.items };
    const parsed = try r.readEnvelope();
    try testing.expectEqual(@as(i64, 0), parsed.status);
    try testing.expect(parsed.is_service_error);
    try testing.expect(parsed.has_payload);

    // decode_ServiceError (like every generated decode_* function) allocates its
    // scratch CBOR value tree from `alloc` and never frees it individually — per
    // its doc comment, pass an arena and free it all at once. This is the same
    // contract typed responses use (see client.gen.zig's submit_task etc).
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    var decoded: types.ServiceError = undefined;
    try codec.decode_ServiceError(arena.allocator(), parsed.payload, &decoded);
    try testing.expectEqual(@as(u64, 404), decoded.code);
    try testing.expectEqualStrings("not found", decoded.message);
}

test "EnvReader: absent payload (control reply, e.g. $pong)" {
    const alloc = testing.allocator;
    var out = std.ArrayList(u8).init(alloc);
    defer out.deinit();
    try appendHead(&out, 5, 1); // map, 1 pair
    try appendText(&out, "variant");
    try appendText(&out, "$pong");

    var r = EnvReader{ .buf = out.items };
    const parsed = try r.readEnvelope();
    try testing.expectEqual(@as(i64, 0), parsed.status);
    try testing.expect(!parsed.has_payload);
    try testing.expect(!parsed.is_service_error);
}

/// A tiny fake corndogs server for the live loopback test below: replies to every
/// request with `status=0` and the request's own inner payload echoed back, EXCEPT
/// a request whose op is "$fail", which gets a non-zero status, and "$serr", which
/// gets a ServiceError variant. Runs until the client closes the connection.
fn fakeServerMain(server: *std.net.Server) void {
    const conn = server.accept() catch return;
    defer conn.stream.close();
    const alloc = testing.allocator;
    while (true) {
        const frame = readFrame(alloc, conn.stream) catch return;
        defer alloc.free(frame);
        if (frame.len == 0) return; // client closed

        var r = EnvReader{ .buf = frame };
        // Re-decode enough of the *request* envelope to find "op" and "payload".
        const top = r.readHeader() catch return;
        if (top.major != 5) return;
        var op: []const u8 = "";
        var payload: []const u8 = "";
        var i: u64 = 0;
        while (i < top.arg) : (i += 1) {
            const key = r.readText() catch return;
            if (std.mem.eql(u8, key, "op")) {
                op = r.readText() catch return;
            } else if (std.mem.eql(u8, key, "payload")) {
                const h = r.readHeader() catch return;
                if (h.major != 6) return;
                const inner = r.readHeader() catch return;
                if (inner.major != 2) return;
                payload = r.take(inner.arg) catch return;
            } else {
                r.skipValue() catch return;
            }
        }

        var reply = std.ArrayList(u8).init(alloc);
        defer reply.deinit();
        if (std.mem.eql(u8, op, "$fail")) {
            appendHead(&reply, 5, 2) catch return; // status, error
            appendText(&reply, "status") catch return;
            appendUint(&reply, 9) catch return;
            appendText(&reply, "error") catch return;
            appendText(&reply, "synthetic failure") catch return;
        } else if (std.mem.eql(u8, op, "$serr")) {
            var se = types.ServiceError{ .code = 42, .message = "nope" };
            const enc = codec.encode_ServiceError(alloc, &se) catch return;
            defer alloc.free(enc);
            appendHead(&reply, 5, 2) catch return; // variant, payload
            appendText(&reply, "variant") catch return;
            appendText(&reply, "ServiceError") catch return;
            appendText(&reply, "payload") catch return;
            appendHead(&reply, 6, TAG_ENCODED_CBOR) catch return;
            appendBytes(&reply, enc) catch return;
        } else if (std.mem.eql(u8, op, OP_PING)) {
            appendHead(&reply, 5, 1) catch return; // variant only, no payload
            appendText(&reply, "variant") catch return;
            appendText(&reply, "$pong") catch return;
        } else {
            appendHead(&reply, 5, 2) catch return; // status=0, payload echoed back
            appendText(&reply, "status") catch return;
            appendUint(&reply, 0) catch return;
            appendText(&reply, "payload") catch return;
            appendHead(&reply, 6, TAG_ENCODED_CBOR) catch return;
            appendBytes(&reply, payload) catch return;
        }
        writeFrame(conn.stream, reply.items) catch return;
    }
}

test "Transport: connect, call, ping, ServiceError, TransportStatus, and close over a real loopback socket" {
    const alloc = testing.allocator;
    const addr = try std.net.Address.parseIp("127.0.0.1", 0);
    var server = try addr.listen(.{ .reuse_address = true });
    defer server.deinit();
    const bound_port = server.listen_address.getPort();

    const server_thread = try std.Thread.spawn(.{}, fakeServerMain, .{&server});
    defer server_thread.join();

    var addr_buf: [64]u8 = undefined;
    const addr_str = try std.fmt.bufPrint(&addr_buf, "127.0.0.1:{d}", .{bound_port});
    var tr = try Transport.connect(alloc, addr_str);
    defer tr.close();

    // Ordinary call: echoed payload comes back unchanged.
    const resp = try tr.call(alloc, "CorndogsService", "SubmitTask", "req-bytes");
    defer alloc.free(resp);
    try testing.expectEqualStrings("req-bytes", resp);

    // Heartbeat one-shot.
    try tr.ping(alloc);

    // Transport-level status != 0.
    {
        const r = tr.call(alloc, "CorndogsService", "$fail", "");
        try testing.expectError(TransportError.TransportStatus, r);
        try testing.expect(tr.last_transport_error != null);
        try testing.expectEqualStrings("synthetic failure", tr.last_transport_error.?);
    }

    // ServiceError variant. Like every generated decode_* function,
    // codec.decode_ServiceError (used internally by parseResponse) allocates its
    // scratch CBOR tree from the `alloc` passed to call() and never frees it
    // individually — pass an arena and free it all at once (same contract the
    // generated typed responses use).
    {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const r = tr.call(arena.allocator(), "CorndogsService", "$serr", "");
        try testing.expectError(TransportError.ServiceErrorOccurred, r);
        try testing.expect(tr.last_service_error != null);
        try testing.expectEqual(@as(u64, 42), tr.last_service_error.?.code);
        try testing.expectEqualStrings("nope", tr.last_service_error.?.message);
    }

    // Background heartbeat: start it, let it fire at least once, stop it.
    const hb = try tr.startHeartbeat(alloc, 5 * std.time.ns_per_ms);
    std.Thread.sleep(30 * std.time.ns_per_ms);
    hb.stop();
}
